import { writeFileSync, readdirSync, readFileSync } from 'node:fs';
import { test } from 'vitest';
import GBNF, { InputParseError, GrammarParseError } from 'gbnf';

const GRAMMAR_DIR = '/workspace/tests/python/iteration/grammars';

const CASES: [string, string][] = [];
for (const file of readdirSync(GRAMMAR_DIR).filter((f) => f.endsWith('.gbnf')).sort()) {
  const grammar = readFileSync(`${GRAMMAR_DIR}/${file}`, 'utf8');
  for (const input of [
    '', '1', '1+', 'a', 'foo', '{', '{"a"', '{"a":1}', '[1,2]', ' ', '\n', 'e4 e5',
    '- item\n- item2', 'int main() {', '漫画', 'ぁ', '(1+2)=3\n', 'x_1 = 2', '"str"',
    'abc\tdef', '1 +2 = 3\n', '99', '\t', '#', 'z', '0', 'null', 'true', '-1.5e10',
  ]) {
    CASES.push([grammar, input]);
  }
}

const BAD_GRAMMARS = [
  '', 'root = "foo"', 'root ::= foo', 'root ::= ([a-z]', 'root ::= foo ::= bar',
  'root ::= *', 'root ::= "foo', 'root ::= [a-z', 'root ::= \\q', '  ', '# only a comment',
  'root ::= "a" # trailing comment\n', 'root ::= [\\x41-\\x5A]', 'root ::= [\\u0041]',
  'root ::= "\\t\\n\\r\\"\\[\\]\\\\"', 'root ::= ("a" | "b")+ "c"?', 'root ::= a-b\na-b ::= "x"',
  'root ::= [^]', 'root ::= [a-]', 'root ::= ()', 'ROOT ::= "a"',
];

const serialize = (grammar: string, input: string) => {
  try {
    let state = GBNF(grammar);
    state = state.add(input);
    return { ok: [...state].map((r) => ({ type: r.type, value: (r as { value?: unknown }).value ?? null })) };
  } catch (err) {
    if (err instanceof InputParseError) {
      return { inputError: err.message, forMostRecent: err.errorForMostRecentInput };
    }
    if (err instanceof GrammarParseError) {
      return { grammarError: err.message };
    }
    return { error: `${(err as Error).message}` };
  }
};

test('dump', () => {
  const out: Record<string, unknown> = {};
  for (const [grammar, input] of CASES) {
    out[JSON.stringify([grammar, input])] = serialize(grammar, input);
  }
  for (const grammar of BAD_GRAMMARS) {
    out[JSON.stringify([grammar, ''])] = serialize(grammar, '');
  }
  writeFileSync('/tmp/ts-out.json', JSON.stringify(out, null, 2));
});

